import{_ as i,l as p,o as a,c as r,v as l,p as n,x as t,d,i as s,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Apple MLX","description":"","frontmatter":{"title":"Apple MLX","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mlx-apple.md","filePath":"llm/mlx-apple.md","lastUpdated":1789023840000}'),m={name:"llm/mlx-apple.md"};function c(P,e,h,M,E,U){const o=p("Mermaid");return a(),r("div",null,[e[1]||(e[1]=l('<h1 id="apple-mlx" tabindex="-1">Apple MLX <a class="header-anchor" href="#apple-mlx" aria-label="Permalink to &quot;Apple MLX&quot;">​</a></h1><div class="epigraph"><p>统一内存让权重、KV 与激活住在同一块 DRAM 里：没有 PCIe 拷贝，但屋顶线换成了内存控制器与 GPU/ANE 能同时咬多少带宽。</p><footer>—— Hannun 等，MLX 框架；Apple Silicon 统一内存是硬件前提</footer></div><p><a href="/llm/openvino">上一课</a>在 Intel 上讲共享内存。Apple Silicon 把 CPU、GPU 做成统一内存（UMA）：MLX 用这点做数组框架，延迟求值、在 GPU 上跑 Transformer。llama.cpp 的 Metal 后端是另一条路径，见 <a href="/llm/llamacpp">llama.cpp</a>。本课写 MLX 的差：Python 研究友好、统一内存上 <em>驻留策略简化</em>、以及 decode 仍被内存带宽绑住——只是没有 PCIe 那一项。不把某一 M 系列芯片的 GB/s 写成科学常数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CUDA 服务的加载是盘 → 主机 → HBM。<a href="/llm/weight-loading-streaming">权重加载</a>的 PCIe 在 Mac 上不存在同一形态：GPU 直接看统一内存中的数组。缺口是：程序员容易以为「没有拷贝 = 没有带宽墙」。decode 每步仍要扫 \\(W+\\mathrm{KV}\\)，墙是 DRAM 控制器。统一内存上 CPU 与 GPU 争同一带宽，一边 Python 预处理、一边 GPU decode，会互相伤害。</p><p>量化（4-bit）同样关键：笔记本级 DRAM 容量是容量墙。MLX 的量化类型与 GGUF k-quant 不是同一码本，质量数字不可直接比。</p><p><span class="marginnote">ANE（神经引擎）与 GPU 不是自动可互换。MLX 主路径是 GPU；把算子下沉 ANE 有形状限制，LLM decode 不总适合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 MLX 实现或社区 LLM 包：权重以框架格式或转换脚本进统一内存，generate 循环在框架内。批处理 \\(B\\gt 1\\) 在本地聊天少见；若做，UMA 上加大 \\(B\\) 仍摊权重，拐点逻辑同前，只是峰值不同。与 Python 互操作：大数组应保持 MLX 端，避免 <code>numpy()</code> 隐式拷到 CPU 再拷回。流式 detokenize 仍在 CPU，注意不要每 token 触发大同步。</p>',9)),(a(),n(A,null,{default:t(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E5%9C%A8%E7%BB%9F%E4%B8%80%E5%86%85%E5%AD%98%22%5D%20--%3E%20GPU%5B%22Metal%20GPU%20%E6%89%AB%20W%2BKV%22%5D%0A%20%20KV%5B%22KV%20%E5%90%8C%E4%B8%80%E5%9D%97%20DRAM%22%5D%20--%3E%20GPU%0A%20%20CPU%5B%22CPU%20%E5%88%86%E8%AF%8D%20%2F%20%E9%87%87%E6%A0%B7%E8%BE%85%E5%8A%A9%22%5D%20--%3E%20BUS%5B%22%E4%BA%89%E7%94%A8%E5%86%85%E5%AD%98%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20GPU%20--%3E%20BUS%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>UMA 消灭设备拷贝，不消灭访存能量与带宽。Horowitz 的 DRAM 能量项仍在。研究迭代（改模型、立刻跑）是 MLX 的强项；多租户 SLA 不是——没有 HBM 池与成熟的连续批生态可与 vLLM 对标。选择 MLX 是为了本地与研究，不是把数据中心服务搬到 Mac Studio 就结束会计。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 MLX 的 eager 研究脚本当生产多用户引擎。不要把 Metal 与 CUDA FA 的加速比横比而不钉 \\(n,B\\)。下一课：浏览器里的 WebGPU，连 Python 都没有。</p><p>出处：MLX 项目（Hannun 等）；Apple Silicon 统一内存硬件文档。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLX 利用 UMA：无 PCIe 拷贝，decode 仍绑 DRAM 带宽。</li><li>CPU 与 GPU 争用同一总线；预处理要让路。</li><li>量化码本与 GGUF 不同，质量分开测。</li><li>适合本地与研究，不是数据中心连续批。</li><li>避免无意义的 <code>numpy()</code> 往返。</li><li>下一课：WebGPU 推理。</li><li>出处：MLX；Apple Silicon 统一内存。</li></ul>',7))])}const B=i(m,[["render",c]]);export{u as __pageData,B as default};
